package chart

import (
	"compress/gzip"
	"encoding/json"
	"fmt"
	"os"
	"slices"
	"testing"
	"time"
)

// Golden values come from the pinned d3-scale version recorded in the
// fixture, generated by scripts/chart-scales-golden.ts with Node in UTC: the
// times of a day's step are a day of the month, as the port's are, and the
// zone of the times is the test's, which is UTC.
func TestTimeMatchesD3(t *testing.T) {
	f, err := os.Open("testdata/time_d3.json.gz")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	z, err := gzip.NewReader(f)
	if err != nil {
		t.Fatal(err)
	}
	defer z.Close()
	var golden struct {
		Version string
		Cases   []struct {
			Domain                 [2]int64
			Count                  int
			Ticks, Nice, NiceTicks []int64
		}
	}
	if err := json.NewDecoder(z).Decode(&golden); err != nil {
		t.Fatal(err)
	}
	if golden.Version != "4.0.2" || len(golden.Cases) == 0 {
		t.Fatalf("invalid d3-scale reference: version %q, %d cases", golden.Version, len(golden.Cases))
	}
	t.Logf("%d time cases of d3-scale %s", len(golden.Cases), golden.Version)
	millis := func(ts []Tick) []int64 {
		if len(ts) == 0 {
			return nil
		}
		out := make([]int64, len(ts))
		for i, tick := range ts {
			out[i] = int64(tick.Value)
		}
		return out
	}
	for i, c := range golden.Cases {
		t.Run(fmt.Sprintf("%d", i), func(t *testing.T) {
			from, to := time.UnixMilli(c.Domain[0]).UTC(), time.UnixMilli(c.Domain[1]).UTC()
			s := NewTime(from, to)
			if got := millis(s.Ticks(c.Count)); !slices.Equal(got, c.Ticks) {
				t.Errorf("Ticks(%d) of %v: %v, want %v", c.Count, c.Domain, got, c.Ticks)
			}
			if c.Nice == nil {
				// d3 leaves a domain that descends, of less than a second,
				// as it is: the step of a reversed pair is negative, and
				// scaleTime.every then gets a millisecond of it. The port
				// rounds such a domain like its ascending twin's.
				up, down := NewTime(to, from).Nice(c.Count), s.Nice(c.Count)
				got, want := [2]int64{down.From.UnixMilli(), down.To.UnixMilli()},
					[2]int64{up.To.UnixMilli(), up.From.UnixMilli()}
				if got != want {
					t.Errorf("Nice(%d) of %v = %v, want the drawn up twin's %v", c.Count, c.Domain, got, want)
				}
				return
			}
			n := s.Nice(c.Count)
			if got, want := [2]int64{n.From.UnixMilli(), n.To.UnixMilli()}, [2]int64{c.Nice[0], c.Nice[1]}; got != want {
				t.Errorf("Nice(%d) of %v = %v, want %v", c.Count, c.Domain, got, want)
			}
			if got := millis(n.Ticks(c.Count)); !slices.Equal(got, c.NiceTicks) {
				t.Errorf("Ticks(%d) of the niced %v: %v, want %v", c.Count, c.Domain, got, c.NiceTicks)
			}
		})
	}
}
